-- =====================================================================
-- Semantic Search Demo Queries
-- =====================================================================
-- pgvector uses the <=> operator for cosine distance. 
-- To get similarity (where 1 is exact match), we do 1 - (embedding <=> query_vector).
-- In the actual app, the query vector is generated by the Node.js API.
-- For this demo, we use a pre-existing row's embedding as the query vector.
-- =====================================================================

-- 1. Find locations semantically similar to a specific location
-- (e.g., "Find sets similar to the Palace Interior Set")
SELECT 
    l.name, 
    l.type, 
    round((1 - (l.embedding <=> q.embedding))::numeric, 3) AS similarity_score
FROM location l, 
     (SELECT embedding FROM location WHERE name = 'Palace Interior Set') q
ORDER BY l.embedding <=> q.embedding 
LIMIT 5;

-- 2. Find equipment semantically similar to a specific piece of equipment
-- (e.g., "Find gear similar to a Steadicam")
SELECT 
    e.name, 
    e.category, 
    round((1 - (e.embedding <=> q.embedding))::numeric, 3) AS similarity_score
FROM equipment e, 
     (SELECT embedding FROM equipment WHERE name ILIKE '%Steadicam%' LIMIT 1) q
ORDER BY e.embedding <=> q.embedding 
LIMIT 5;

)
EXPLAIN ANALYZE 
SELECT name FROM location 
ORDER BY embedding <=> (SELECT embedding FROM location LIMIT 1) 
LIMIT 5;